local function submitKey(key)
    key = M.cleanKey(key)
    if key == "" then
        Library:Notify({Title="⚠️ Kein Schlüssel eingegeben", Description="Bitte gib deinen Schlüssel ein.", Time=3})
        return
    end
    Library:Notify({Title="🔑 Überprüfung", Description="Schlüssel wird überprüft...", Time=2})

    -- NEW backend: validate the key + get this game's scripts in one call.
    local data, err = M.validateKeyNew(key)
    if type(data) ~= "table" then
        local msg = "Dieser Schlüssel ist ungültig. Bitte überprüfe ihn und versuche es erneut."
        if err == "wrong_game" then
            msg = "Dieser Schlüssel ist für ein anderes Spiel. Hol dir einen Schlüssel für dieses Spiel."
        elseif err == "network" or err == "no_request" then
            msg = "Netzwerkfehler. Bitte versuche es erneut."
        end
        Library:Notify({Title="❌ Ungültiger Schlüssel", Description=msg, Time=5})
        return
    end

    local scripts = data.scripts or {}
    if #scripts == 0 then
        Library:Notify({Title="🔓 Schlüssel gültig", Description="Für dieses Spiel sind noch keine Skripte festgelegt.", Time=5})
        return
    end

    -- Valid — remember the key for next time, close this GUI, show the selector.
    M.saveKeyLocal(key)
    Library:Notify({
        Title = "🔓 Schlüssel gültig",
        Description = (#scripts == 1) and "Skript wird geladen..." or "Wähle ein Skript...",
        Time = 3,
    })
    task.wait(0.4)
    pcall(function() Library:Unload() end)
    M.showSelector(scripts)
end

local function readKeyFromBox()
    local raw
    pcall(function()
        local holder = Options and Options.KeyInput and Options.KeyInput.Holder
        local box = holder and holder:FindFirstChildOfClass("TextBox")
        if box then raw = box.Text end
    end)
    local key = M.cleanKey(raw)
    if key == "" then key = M.cleanKey(Options and Options.KeyInput and Options.KeyInput.Value) end
    if key == "" then key = M.cleanKey(keyInputValue) end
    return key
end

